package server

import (
	"net/http"
	"unicode/utf8"

	"github.com/extube/bleak-node/internal/db"
	"github.com/extube/bleak-node/internal/model"
)

// CreateUserRequest is the body for POST /api/room/{room}/user.
// The user address and the greeting (hello message) are generated by the
// server and must not be provided. The user language is inherited from the
// room: the greeting is generated in the room language.
// Joining requires a currently-valid 6-digit invite code of the room
// (CONCEPT.md §7.2) and the client-generated persona token (§7.1): the
// server stores only its SHA-256 hash.
type CreateUserRequest struct {
	Name       string `json:"name"`
	PublicBio  string `json:"public_bio"`
	PrivateBio string `json:"private_bio"`
	Token      string `json:"token"`
	InviteCode string `json:"invite_code"`
}

// UpdateUserRequest is the body for PUT /api/room/{room}/user/{address}.
type UpdateUserRequest struct {
	Name       *string `json:"name"`
	PublicBio  *string `json:"public_bio"`
	PrivateBio *string `json:"private_bio"`
	// Active opts the persona in/out of the auto-matchmaking worker
	// (feature #36); omitted keeps the current flag.
	Active *bool `json:"active"`
}

const maxUserBioLen = 255

// CreateUser adds a user to a room. The join is gated by a valid room
// invite code (rate-limited per source) and carries the client-generated
// persona token.
//
//	@Summary		create user in room
//	@Description	Creates a user linked to the room. The room must exist and not be deleted. Joining requires a currently-valid, unrevoked, unexpired invite_code of the room (attempts are rate-limited per source) and the client-generated persona token in the body (only its SHA-256 hash is stored).
//	@Tags			users
//	@Accept			json
//	@Produce		json
//	@Param			room	path	string				true	"Room address"
//	@Param			request	body	CreateUserRequest	true	"User to create (with invite code and persona token)"
//	@Success		201	{object}	model.User
//	@Failure		400	{object}	string
//	@Failure		403	{object}	string
//	@Failure		404	{object}	string
//	@Failure		409	{object}	string
//	@Failure		429	{object}	string
//	@Router			/api/room/{room}/user [post]
func (s *Server) CreateUser(w http.ResponseWriter, r *http.Request) {
	var req CreateUserRequest
	if err := decodeJSON(r, &req); err != nil {
		respond(w, http.StatusBadRequest, message(err))
		return
	}
	if req.Name == "" {
		respond(w, http.StatusBadRequest, "name is required")
		return
	}
	if n := utf8.RuneCountInString(req.PublicBio); n > maxUserBioLen {
		respond(w, http.StatusBadRequest, "public_bio must be at most 255 symbols")
		return
	}
	if n := utf8.RuneCountInString(req.PrivateBio); n > maxUserBioLen {
		respond(w, http.StatusBadRequest, "private_bio must be at most 255 symbols")
		return
	}
	if !validateToken(req.Token) {
		respond(w, http.StatusBadRequest,
			"token is required: a client-generated secret of at least 32 symbols")
		return
	}
	if req.InviteCode == "" {
		respond(w, http.StatusBadRequest, "invite_code is required")
		return
	}

	// The 6-digit invite space is brute-forceable: join attempts are
	// rate-limited per source (CONCEPT.md §7.4).
	if !s.rateLimit(w, r, "join") {
		return
	}

	// The greeting is generated in the room language: a room is
	// single-language end to end, so the user inherits it.
	room, err := s.db.GetRoom(r.Context(), r.PathValue("room"))
	if err != nil {
		s.mapError(w, err)
		return
	}
	valid, err := s.db.ValidRoomInvite(r.Context(), room.Address, req.InviteCode)
	if err != nil {
		s.mapError(w, err)
		return
	}
	if !valid {
		forbidden(w, "invite_code is invalid, expired or revoked")
		return
	}
	user := model.User{
		Name:       req.Name,
		PublicBio:  req.PublicBio,
		PrivateBio: req.PrivateBio,
		Language:   room.Language,
	}
	user.Greeting = s.greetingFor(req.Name, req.PublicBio, req.PrivateBio, room.Language)
	if err := s.db.CreateUser(r.Context(), r.PathValue("room"), &user, db.HashToken(req.Token)); err != nil {
		s.mapError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, user)
}

// ListRoomUsers lists users of a room. Public read; private_bio is a
// gated field (CONCEPT.md §7.1) and is never returned in the list.
//
//	@Summary		list users of a room
//	@Description	Returns all non-deleted users linked to the room. Public read: private_bio is a gated field and is blanked in list responses.
//	@Tags			users
//	@Produce		json
//	@Param			room	path	string	true	"Room address"
//	@Success		200	{array}	model.User
//	@Router			/api/room/{room}/user [get]
func (s *Server) ListRoomUsers(w http.ResponseWriter, r *http.Request) {
	users, err := s.db.ListRoomUsers(r.Context(), r.PathValue("room"))
	if err != nil {
		s.mapError(w, err)
		return
	}
	// private_bio is gated: blank it for every public list entry.
	for i := range users {
		users[i].PrivateBio = ""
	}
	writeJSON(w, http.StatusOK, users)
}

// GetUser returns a single user of a room. Public read; private_bio and
// the derived mutual_code_live flag are returned ONLY to a caller
// presenting that persona's token.
//
//	@Summary		get user
//	@Description	Returns a non-deleted user linked to the room. Public read: private_bio (and the derived mutual_code_live flag) are returned ONLY when the request presents that persona's Bearer token.
//	@Tags			users
//	@Produce		json
//	@Param			room		path	string	true	"Room address"
//	@Param			address		path	string	true	"User address"
//	@Success		200	{object}	model.User
//	@Failure		404	{object}	string
//	@Router			/api/room/{room}/user/{address} [get]
func (s *Server) GetUser(w http.ResponseWriter, r *http.Request) {
	user, err := s.db.GetUser(r.Context(), r.PathValue("room"), r.PathValue("address"))
	if err != nil {
		s.mapError(w, err)
		return
	}
	if s.userTokenMatches(r, user.Room, user.Address) {
		live, err := s.db.UserMutualCodeLive(r.Context(), user.Room, user.Address)
		if err != nil {
			s.mapError(w, err)
			return
		}
		user.MutualCodeLive = &live
	} else {
		user.PrivateBio = ""
	}
	writeJSON(w, http.StatusOK, user)
}

// UpdateUser partially updates a user.
//
//	@Summary		update user
//	@Description	Updates name, bios and the active flag (the auto-matchmaking opt-out, feature #36) of a user. Omitted fields keep their value.
//	@Tags			users
//	@Accept			json
//	@Produce		json
//	@Param			room		path	string				true	"Room address"
//	@Param			address		path	string				true	"User address"
//	@Param			request		body	UpdateUserRequest	true	"Fields to update"
//	@Success		200	{object}	model.User
//	@Failure		400	{object}	string
//	@Failure		401	{object}	string
//	@Failure		403	{object}	string
//	@Failure		404	{object}	string
//	@Router			/api/room/{room}/user/{address} [put]
func (s *Server) UpdateUser(w http.ResponseWriter, r *http.Request) {
	if !s.authUserToken(w, r, r.PathValue("room"), r.PathValue("address")) {
		return
	}
	var req UpdateUserRequest
	if err := decodeJSON(r, &req); err != nil {
		respond(w, http.StatusBadRequest, message(err))
		return
	}
	if req.Name != nil && *req.Name == "" {
		respond(w, http.StatusBadRequest, "name must be non-empty")
		return
	}
	if req.PublicBio != nil && utf8.RuneCountInString(*req.PublicBio) > maxUserBioLen {
		respond(w, http.StatusBadRequest, "public_bio must be at most 255 symbols")
		return
	}
	if req.PrivateBio != nil && utf8.RuneCountInString(*req.PrivateBio) > maxUserBioLen {
		respond(w, http.StatusBadRequest, "private_bio must be at most 255 symbols")
		return
	}

	user, err := s.db.UpdateUser(r.Context(), r.PathValue("room"), r.PathValue("address"),
		req.Name, req.PublicBio, req.PrivateBio, req.Active)
	if err != nil {
		s.mapError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, user)
}

// DeleteUser soft-deletes a user.
//
//	@Summary		delete user
//	@Description	Soft-deletes a user of the room.
//	@Tags			users
//	@Security		UserToken
//	@Param			room	path	string	true	"Room address"
//	@Param			address	path	string	true	"User address"
//	@Success		200	{object}	model.User
//	@Failure		401	{object}	string
//	@Failure		403	{object}	string
//	@Failure		404	{object}	string
//	@Router			/api/room/{room}/user/{address} [delete]
func (s *Server) DeleteUser(w http.ResponseWriter, r *http.Request) {
	if !s.authUserToken(w, r, r.PathValue("room"), r.PathValue("address")) {
		return
	}
	user, err := s.db.DeleteUser(r.Context(), r.PathValue("room"), r.PathValue("address"))
	if err != nil {
		s.mapError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, user)
}
